const graphemes = new Intl.Segmenter("en", { granularity: "grapheme" });
const words = new Intl.Segmenter(undefined, { granularity: "word" });
const sentences = new Intl.Segmenter(undefined, { granularity: "sentence" });
const plain = new Intl.Segmenter(undefined, {});

export function columns(text) {
    return [...graphemes.segment(text)].map((part) => part.segment).join("|");
}

export function plainColumns(text) {
    return [...plain.segment(text)].length;
}

export function describe() {
    return `${typeof words} ${typeof sentences}`;
}
